def solution(tape: str) -> str:
    """
    Interpret a Ticker program and return the output tape.

    Parameters
    ----------
    tape : str
        The Ticker program as a string.

    Returns
    -------
    str
        The output tape.
    """
    selector = 0
    data = [0]
    output = []

    for char in tape:
        if char == '>':
            selector += 1
        elif char == '<':
            selector -= 1
        elif char == '*':
            if selector < 0 or selector >= len(data):
                continue
            output.append(chr(data[selector]))
        elif char == '+':
            if selector < 0 or selector >= len(data):
                continue
            data[selector] = (data[selector] + 1) % 256
        elif char == '-':
            if selector < 0 or selector >= len(data):
                continue
            data[selector] = (data[selector] - 1) % 256
        elif char == '/':
            if selector < 0 or selector >= len(data):
                continue
            data[selector] = 0
        elif char == '!':
            data.append(0)

    return ''.join(output)
