def solution(h: int) -> list[list[int]]:
    """
    Return a list containing:
        - the highest abundant number ≤ h
        - its abundance
    """
    def is_abundant(n: int) -> bool:
        """
        Return True if n is abundant, False otherwise.
        """
        if n <= 1:
            return False
        total: int = 1
        for i in range(2, n):
            if n % i == 0:
                total += i
            if total > n:
                return True
        return False

    def find_abundant(limit: int) -> int:
        """
        Yield abundant numbers in ascending order up to limit.
        """
        for n in range(2, limit + 1):
            if is_abundant(n):
                yield n

    max_abundant: int = 0
    max_abundance: int = 0
    for n in find_abundant(h):
        if n > max_abundant:
            max_abundant = n
            max_abundance = n - sum(1 for _ in range(1, n))
    return [[max_abundant], [max_abundance]]
```

