def solution(n: int, notes: list[int]) -> list[int] | int:
    b = [0] * n
    for i in range(n):
        b[i] = i + 1
        if i > 0:
            if notes[i] < notes[i - 1]:
                if b[i] <= b[i - 1]:
                    return -1
            elif notes[i] > notes[i - 1]:
                if b[i] >= b[i - 1]:
                    return -1
            elif notes[i] == notes[i - 1]:
                if b[i] == b[i - 1]:
                    return -1
    return b
