I’ll use a sieve to precompute prime factors for each number, then group them by prime and count occurrences. The GCD of a set is the product of each prime raised to the minimum of its counts across all numbers. If removing any number increases this product, we’ve found a solution.

def solution(n: int, numbers: list[int]) -> int:
    """
    Return the minimum number of integers to remove so that the GCD of the remaining
    integers is greater than the GCD of all n integers.

    Parameters
    ----------
    n : int
        Number of integers.
    numbers : list[int]
        List of n positive integers.

    Returns
    -------
    int
        Minimum number of integers to remove, or -1 if no solution exists.
    """
    # Precompute prime factors for each number
    max_num = max(numbers)
    primes = [2]
    for p in range(3, int(max_num ** 0.5) + 1, 2):
        if p in primes:
            continue
        primes.append(p)
    factors = [[] for _ in range(n)]
    for i, num in enumerate(numbers):
        if num == 1:
            continue
        for p in primes:
            while num % p == 0:
                factors[i].append(p)
                num //= p
        if num > 1:
            factors[i].append(num)

    # Group factors by prime
    grouped = {}
    for i in range(n):
        for p in factors[i]:
            if p not in grouped:
                grouped[p] = []
            grouped[p].append(i)

    # Compute GCD of all numbers
    all_gcd = 1
    for p in primes:
        min_count = n
        for i in range(n):
            if p in factors[i]:
                min_count = min(min_count, factors[i].count(p))
        all_gcd *= p ** min_count

    # Check if removing any number increases GCD
    for p in grouped:
        for i in grouped[p]:
            # Remove number i
            new_gcd = all_gcd
            for j in range(n):
                if j == i:
                    continue
                for q in factors[j]:
                    if q == p:
                        min_count = min(min_count, factors[j].count(q))
                    else:
                        min_count = n
                new_gcd *= q ** min_count
            if new_gcd > all_gcd:
                return 1
    return -1
